def count_words(text):
    return len(text.split())


def wrap(text, width):
    lines = []
    cur = ""
    for w in text.split():
        extra = len(w) + (1 if cur else 0)
        # Check if adding this word with space exceeds width
        can_add_space = not (cur and len(cur) == 0 or extra > width - len(cur))

        if can_add_space:
            cur += " " + w
        elif extra <= width - len(cur):
            cur += w
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines
